// TOCTOU: a `cwd` accessor that answers differently on each read. After pinning, Node must see
// the FIRST answer, because the object it receives has no accessor left on it at all.
exports.spawnWithFlipFloppingCwd = (first, second) => {
  const cp = require("child_process");
  let reads = 0;
  const r = cp.spawnSync(process.execPath, ["-e", "process.stdout.write(process.cwd())"], {
    encoding: "utf8",
    get cwd() {
      reads += 1;
      return reads === 1 ? first : second;
    },
  });
  return { cwd: r.stdout, reads, error: r.error ? r.error.code : undefined };
};

// TOCTOU, the sharp version. `execFileSync` reads `options.argv0` FIVE times: twice to validate
// it (normalizeExecFileArgs) and again in the `{ __proto__: null, ...options }` spread inside
// normalizeSpawnArguments, and it is that later read that becomes the child's argv[0]. Un-shimmed
// Node therefore validates one value and executes another. Pinning collapses all of it to one
// read, so the answer capwall saw is the answer Node acts on.
exports.execFileSyncWithFlipFloppingArgv0 = (early, late) => {
  const cp = require("child_process");
  let reads = 0;
  const out = cp.execFileSync(process.execPath, ["-e", "process.stdout.write(process.argv0)"], {
    encoding: "utf8",
    get argv0() {
      reads += 1;
      return reads <= 2 ? early : late;
    },
  });
  return { argv0: out, reads };
};

// ── LEGITIMATE USE. Each of these is an ordinary spawn by a package that holds the grant; the
// child prints its own environment so a test can assert it received the right one.
const PRINT_ENV89 = "process.stdout.write(JSON.stringify(process.env))";
const PRINT_ENV_CMD89 = () =>
  `"${process.execPath}" -e "process.stdout.write(JSON.stringify(process.env))"`;

exports.spawnSyncEnv = (options) => {
  const cp = require("child_process");
  const r = cp.spawnSync(process.execPath, ["-e", PRINT_ENV89], { encoding: "utf8", ...options });
  if (r.error) throw r.error;
  return JSON.parse(r.stdout);
};

// `env: process.env` — an ordinary spelling of "inherit" that hands the shim the read PROXY.
// Snapshotting that through the gate would soft-deny every key and launch the child with a
// nearly empty environment, while filling the audit log with ~80 spurious denials.
exports.spawnSyncEnvInheritExplicit = () => {
  const cp = require("child_process");
  const r = cp.spawnSync(process.execPath, ["-e", PRINT_ENV89], {
    encoding: "utf8",
    env: process.env,
  });
  if (r.error) throw r.error;
  return JSON.parse(r.stdout);
};

exports.execFileSyncEnv = (options) => {
  const cp = require("child_process");
  return JSON.parse(
    cp.execFileSync(process.execPath, ["-e", PRINT_ENV89], { encoding: "utf8", ...options }),
  );
};

exports.execSyncEnv = (options) => {
  const cp = require("child_process");
  return JSON.parse(cp.execSync(PRINT_ENV_CMD89(), { encoding: "utf8", ...options }));
};

// execFile/exec in their CALLBACK forms — the shapes with no options slot at all, where capwall
// has to splice one in ahead of the callback rather than replace an argument.
exports.execFileEnvCallbackForm = () =>
  new Promise((resolve, reject) => {
    const cp = require("child_process");
    cp.execFile(process.execPath, ["-e", PRINT_ENV89], (err, stdout) => {
      if (err) {
        reject(err);
        return;
      }
      resolve(JSON.parse(stdout));
    });
  });

exports.execEnvCallbackForm = () =>
  new Promise((resolve, reject) => {
    const cp = require("child_process");
    cp.exec(PRINT_ENV_CMD89(), (err, stdout) => {
      if (err) {
        reject(err);
        return;
      }
      resolve(JSON.parse(stdout));
    });
  });

exports.execFileEnvWithOptions = (options) =>
  new Promise((resolve, reject) => {
    const cp = require("child_process");
    cp.execFile(
      process.execPath,
      ["-e", PRINT_ENV89],
      { encoding: "utf8", ...options },
      (err, stdout) => {
        if (err) {
          reject(err);
          return;
        }
        resolve(JSON.parse(stdout));
      },
    );
  });

exports.forkEnv = (modulePath, options) =>
  new Promise((resolve, reject) => {
    const cp = require("child_process");
    // `execArgv: []` so the child does not inherit the test runner's own flags.
    const child = cp.fork(modulePath, [], { silent: true, execArgv: [], ...options });
    let out = "";
    child.stdout.on("data", (c) => (out += c));
    child.on("error", reject);
    child.on("exit", () => {
      try {
        resolve(JSON.parse(out));
      } catch (err) {
        reject(err);
      }
    });
  });

// Ordinary spawn shapes that must keep working unchanged (argument-normalization coverage).
exports.spawnSyncNoOptions = () => {
  const cp = require("child_process");
  const [file, args] = NOOP89();
  return cp.spawnSync(file, args).status;
};
exports.spawnSyncOptionsAsSecondArg = () => {
  const cp = require("child_process");
  // `spawnSync(file, options)` — Node's "args[1] is the options bag" branch.
  return cp.spawnSync(process.execPath, { input: "", encoding: "utf8" }).status;
};
exports.spawnSyncRejectsNullOptions = () => {
  const cp = require("child_process");
  const [file, args] = NOOP89();
  try {
    cp.spawnSync(file, args, null);
    return null;
  } catch (err) {
    return err.code;
  }
};

// #88 — the guarded `http.globalAgent` view is capwall's Proxy over a PROCESS-GLOBAL agent, and
// until this issue it had only a `get` trap: every other operation took its default behaviour and
// forwarded straight to the real agent, so a dependency could permanently mutate it — and
// `Object.freeze` on it broke the HTTP client for the whole process — through capwall's own
// guarded view, with `uninstall()` unable to take any of it back. This runs the reported PoC's
// steps from inside a real dependency (sloppy mode, as a CJS package is) and reports what each
// one did; the test then asserts the REAL agent is untouched, before and after teardown.
exports.tamperWithGlobalAgent = () => {
  const ga = require("http").globalAgent;
  const attempt = (fn) => {
    try {
      return { ok: true, value: fn() };
    } catch (err) {
      return { ok: false, error: err.constructor.name };
    }
  };
  return {
    // A write to a GUARDED method: kept in capwall's per-view shadow, never forwarded.
    write: attempt(() => {
      ga.createConnection = function evilConn() {
        return "EVIL SOCKET";
      };
      return typeof ga.createConnection;
    }),
    // Structural operations: refused outright, whatever the key.
    defineProperty: attempt(() => {
      Object.defineProperty(ga, "createConnection", {
        value: function evil2() {},
        writable: true,
        configurable: true,
        enumerable: true,
      });
      return true;
    }),
    deleteGuarded: attempt(() => delete ga.createConnection),
    deleteState: attempt(() => delete ga.maxSockets),
    freeze: attempt(() => {
      Object.freeze(ga);
      return Object.isFrozen(ga);
    }),
    setProto: attempt(() => {
      Object.setPrototypeOf(ga, null);
      return true;
    }),
    // The ONE deliberate exception: live pool state stays shared with the real agent, because a
    // private copy would silently detune the default request path (see docs/threat-model.md).
    tunePool: attempt(() => {
      ga.maxSockets = 3;
      return ga.maxSockets;
    }),
  };
};

// ═════════════════════════════════════════════════════════════════════════════════════════════
// #90 — CROSS-SUBSYSTEM COMPOSITION. Two of capwall's shims deliberately open a narrow,
// dynamically-scoped AUTHORIZATION while a real call is on the stack:
//
//   · `child_process` authorizes a fixed set of non-secret env keys for the duration of the real
//     spawn (`withAuthorizedEnvKeys`, shims/runtime.ts) — what is left of #89's process-wide
//     `suspendEnvGate`;
//   · `dgram` arms a single-use replay authorization for the duration of an ALREADY-GUARDED send
//     (`dgramAuthorization`, shims/net.ts), so Node's auto-bind replay is not re-guarded.
//
// Both windows are reachable by caller-controlled code — a getter on a spawn option, an accessor
// on an element of a `send` buffer LIST — which is exactly what made #89 a HIGH. The helpers
// below take a NAMED operation rather than a caller-supplied closure, deliberately: a closure
// passed in from the test file would put an application frame nearest on the stack and attribute
// to `<app>`, which is exempt, so the test would prove nothing. Naming the op keeps the frame
// that matters inside a real package.
//
// Every helper returns `{ inside, outside }` — the SAME operation attempted from inside the
// window and from outside it. The invariant the matrix asserts is that the two are identical:
// an authorization for one call is an authorization for nothing else, on no other subsystem,
// for no other package.
// ═════════════════════════════════════════════════════════════════════════════════════════════

/** Named capability operations. `self:*` run as fixture-dep; `other:*` run as fixture-envpeek,
 * a package that holds no grant of any kind, so they answer the "does A's window open something
 * for B?" half. */
const WINDOW_OPS = {
  "self:env": (key) => process.env[key],
  "self:envHarvest": () =>
    Object.values({ ...process.env }).filter((v) => v !== undefined).length,
  "self:fs": () => fs.readFileSync(DATA, "utf8"),
  "self:net": (host, port) => {
    const s = require("net").connect({ host, port });
    s.on("error", () => {});
    s.destroy();
    return "connected";
  },
  "self:dgram": (host, port) => {
    const s = makeUdpSocket("factory");
    try {
      s.send(Buffer.from("x"), port, host, () => closeQuietly(s));
      return "sent";
    } catch (e) {
      closeQuietly(s);
      throw e;
    }
  },
  "self:spawn": () => require("child_process").spawnSync(process.execPath, ["-e", ""]).status,
  "self:vm": () => require("vm").runInNewContext("1+1"),
  "other:env": (key) => require("fixture-envpeek").read(key),
  "other:envHarvest": () =>
    Object.values(require("fixture-envpeek").readAll()).filter((v) => v !== undefined).length,
  "other:fs": () => require("fixture-envpeek").readFile(DATA),
  "other:net": (host, port) => require("fixture-envpeek").connect(host, port),
  "other:dgram": (host, port) => require("fixture-envpeek").udpSend(host, port),
  "other:spawn": () => require("fixture-envpeek").spawn(),
  "other:vm": () => require("fixture-envpeek").runVm("1+1"),
};

/** Run one named op, reporting the OUTCOME rather than throwing — the tests compare outcomes
 * inside and outside a window, and a throw on either side must be observable, not fatal. */
function runWindowOp(op, args) {
  try {
    return { ok: true, value: WINDOW_OPS[op](...args) };
  } catch (e) {
    return { ok: false, error: e.name };
  }
}

/**
 * Run `op` from a getter on a spawn options object — i.e. from inside the real spawn, where the
 * child_process shim's env authorization is live — and again from outside it.
 */
exports.duringSpawnWindow = (op, args = []) => {
  const cp = require("child_process");
  const [file, argv] = NOOP89();
  let inside;
  cp.spawnSync(file, argv, {
    get cwd() {
      inside = runWindowOp(op, args);
      return undefined;
    },
  });
  return { inside, outside: runWindowOp(op, args) };
};

/**
 * Run `op` from an accessor on an element of the buffer LIST of an ALLOWED `dgram` send — i.e.
 * from inside the window in which capwall's replay authorization for that one send is armed.
 * `cb({ inside, outside })`, after the send has settled.
 */
exports.duringAuthorizedDgramSend = (allowed, op, args, cb) => {
  const s = makeUdpSocket("factory");
  let inside;
  const list = [];
  Object.defineProperty(list, 0, {
    get() {
      if (inside === undefined) inside = runWindowOp(op, args);
      return Buffer.from("x");
    },
    enumerable: true,
    configurable: true,
  });
  list.length = 1;
  s.send(list, allowed.port, allowed.host, () => {});
  const outside = runWindowOp(op, args);
  setTimeout(() => {
    closeQuietly(s);
    cb({ inside, outside });
  }, 50);
};

/** The same operation with no window open at all — the control arm. */
exports.runOp = (op, args = []) => runWindowOp(op, args);

// ─── #90 — captured-vs-fresh references, for EVERY shim rather than just `fs` ─────────────────
// #87 turned on one variable: WHEN a dependency captured its reference. `readData` /
// `readDataFreshRequire` pinned that for `fs`; the divergence it found (`process.env` re-pointed
// while `fs` did not) is a cross-shim property, so the lifecycle matrix needs the same pair for
// every mediated module. Captured HERE, at load time, exactly as a real dependency does.
const capturedNet = require("net");
const capturedHttp = require("http");
const capturedDgram = require("dgram");
const capturedCp = require("child_process");
const capturedVm = require("vm");
const capturedWt = require("worker_threads");

exports.capturedOps = {
  fs: () => fs.readFileSync(DATA, "utf8"),
  net: (host, port) => {
    const s = capturedNet.connect({ host, port });
    s.on("error", () => {});
    s.destroy();
    return "connected";
  },
  http: (host, port) => {
    const req = capturedHttp.request({ host, port, method: "GET", path: "/" });
    req.on("error", () => {});
    req.destroy();
    return "requested";
  },
  dgram: (host, port) => {
    const s = capturedDgram.createSocket("udp4");
    try {
      s.send(Buffer.from("x"), port, host, () => closeQuietly(s));
      return "sent";
    } catch (e) {
      closeQuietly(s);
      throw e;
    }
  },
  child_process: () => capturedCp.spawnSync(process.execPath, ["-e", ""]).status,
  vm: () => capturedVm.runInNewContext("1+1"),
  worker_threads: () => {
    const w = new capturedWt.Worker("", { eval: true });
    void w.terminate();
    return "spawned";
  },
  env: (key) => capturedEnv[key],
};

exports.freshOps = {
  fs: () => require("fs").readFileSync(DATA, "utf8"),
  net: (host, port) => {
    const s = require("net").connect({ host, port });
    s.on("error", () => {});
    s.destroy();
    return "connected";
  },
  http: (host, port) => {
    const req = require("http").request({ host, port, method: "GET", path: "/" });
    req.on("error", () => {});
    req.destroy();
    return "requested";
  },
  dgram: (host, port) => {
    const s = require("dgram").createSocket("udp4");
    try {
      s.send(Buffer.from("x"), port, host, () => closeQuietly(s));
      return "sent";
    } catch (e) {
      closeQuietly(s);
      throw e;
    }
  },
  child_process: () => require("child_process").spawnSync(process.execPath, ["-e", ""]).status,
  vm: () => require("vm").runInNewContext("1+1"),
  worker_threads: () => {
    const { Worker } = require("worker_threads");
    const w = new Worker("", { eval: true });
    void w.terminate();
    return "spawned";
  },
  env: (key) => process.env[key],
};

/** Attempt one op from a family, reporting the outcome so a test can compare the two families
 * step by step across an install/uninstall/reinstall sequence. */
exports.tryOp = (family, name, args = []) => {
  const table = family === "captured" ? exports.capturedOps : exports.freshOps;
  try {
    return { ok: true, value: table[name](...args) };
  } catch (e) {
    return { ok: false, error: e.name };
  }
};

// ─── #90 — surfaces the hardened × ALLOWED matrix needs and nothing else exercised ────────────
// Every hardened-mode test before #90 asserted that a DENIED thing stays denied or that a PATCH
// attempt fails. #86 was the opposite: under CAPWALL_HARDENED=1 every GRANTED dgram send threw.
// Closing that row needs an allowed-path helper for each guarded surface, including the two that
// had none.

/** h2c — plaintext HTTP/2, so no certificate is involved. The session is closed immediately;
 * the test only cares whether the guard let the connect through. */
exports.http2Connect = (host, port) => {
  const s = require("http2").connect(`http://${host}:${port}`);
  s.on("error", () => {});
  s.close();
  return "connected";
};

/** A DIRECT `Module.prototype._compile(source, filename)` — the #93 capability. `filename` is
 * caller-chosen, which is the whole point: compiling under a name outside this package is what
 * the `compile` grant gates. */
exports.compileUnder = (filename, source) => {
  const NodeModule = require("module");
  const m = new NodeModule(filename, null);
  m.filename = filename;
  m.paths = [];
  m._compile(source ?? "module.exports = 42;", filename);
  return m.exports;
};

// ═════════════════════════════════════════════════════════════════════════════════════════════
// #106 — `fs.glob` / `fs.globSync` / `fs.promises.glob` (Node ≥22 only). Directory ENUMERATION
// through a pattern rather than a path. Every helper is called from this package's own frame so
// the walk is attributed to "fixture-dep" and not to <app>.
//
// `globSurface()` is what makes the Node-20 row of the matrix an assertion instead of a skip:
// the test asserts the family is absent there, and absent through the SHIM too (the shim must
// not invent methods the runtime does not have).
// ═════════════════════════════════════════════════════════════════════════════════════════════

exports.globSurface = () => ({
  glob: typeof fs.glob,
  globSync: typeof fs.globSync,
  promisesGlob: typeof fsPromises.glob,
});

exports.globSync = (pattern, options) =>
  options === undefined ? fs.globSync(pattern) : fs.globSync(pattern, options);

/** Callback form. Resolves `{ err, matches }` — a denial must arrive through the CALLBACK, the
 * channel real `fs.glob` uses, not as a synchronous throw. A sync throw propagates instead, and
 * the test can tell the two apart. */
exports.globCallback = (pattern, options) =>
  new Promise((resolve) => {
    const done = (err, matches) => resolve({ err, matches });
    if (options === undefined) fs.glob(pattern, done);
    else fs.glob(pattern, options, done);
  });

/** `fsPromises.glob` returns an ASYNC ITERATOR, not a promise; a denial has to surface at the
 * first `next()`. Returns `{ ok, matches }` or `{ ok: false, error }`. */
exports.globPromises = async (pattern, options) => {
  const iterator = options === undefined ? fsPromises.glob(pattern) : fsPromises.glob(pattern, options);
  const matches = [];
  try {
    for await (const m of iterator) matches.push(m);
    return { ok: true, matches };
  } catch (err) {
    return { ok: false, error: err.name, message: err.message };
  }
};
/** Does the denied promises form at least LOOK like the real one (an async iterator)? */
exports.globPromisesIsAsyncIterator = (pattern, options) => {
  const it = fsPromises.glob(pattern, options);
  return it !== null && typeof it === "object" && typeof it[Symbol.asyncIterator] === "function";
};

/** TOCTOU on `options.cwd`: an accessor that answers `first` once and `second` forever after.
 * Un-pinned, capwall guards `first` and Node walks `second`. Returns the matches plus the number
 * of times the accessor ran — which must be 1, because the object Node receives has no getter. */
exports.globSyncFlipFloppingCwd = (pattern, first, second) => {
  let reads = 0;
  const matches = fs.globSync(pattern, {
    get cwd() {
      reads += 1;
      return reads === 1 ? first : second;
    },
  });
  return { matches, reads };
};

/** `options.cwd` as a file URL — Node converts it, so capwall must guard the converted path. */
exports.globSyncUrlCwd = (pattern, dir) =>
  fs.globSync(pattern, { cwd: require("url").pathToFileURL(dir) });

/** An array of patterns: one enumeration, and one decision, per pattern. */
exports.globSyncMany = (patterns, options) => fs.globSync(patterns, options);
